def seed_categories_and_existing_expenses(apps, schema_editor):
    BusinessProfile = apps.get_model("accounts", "BusinessProfile")
    Invoice = apps.get_model("invoices", "Invoice")
    ExpenseCategory = apps.get_model("expenses", "ExpenseCategory")
    ExpenseDetail = apps.get_model("expenses", "ExpenseDetail")
    alias = schema_editor.connection.alias

    for business in BusinessProfile.objects.using(alias).all():
        categories = {}
        for name in DEFAULT_CATEGORIES:
            category, _ = ExpenseCategory.objects.using(alias).get_or_create(
                business_id=business.pk,
                name=name,
                defaults={"is_default": True},
            )
            categories[name] = category

    for invoice in Invoice.objects.using(alias).filter(invoice_type="expense").iterator():
        business = BusinessProfile.objects.using(alias).filter(user_id=invoice.user_id).first()
        if business is None:
            continue
        category, _ = ExpenseCategory.objects.using(alias).get_or_create(
            business_id=business.pk,
            name="Miscellaneous",
            defaults={"is_default": True},
        )
        ExpenseDetail.objects.using(alias).get_or_create(
            invoice_id=invoice.pk,
            defaults={
                "category_id": category.pk,
                "title": (invoice.supplier_name or invoice.invoice_number)[:200],
                "reference_number": invoice.invoice_number,
            },
        )


